mapper.sql:
WHERE 1=1

  AND A.CMPNY_CD != 'prafta_system_admin'

  AND A.CMPNY_NM LIKE CONCAT('%', #{cmpnyNm}, '%')


  AND A.CONTRACT_YN = #{contractYn}


  AND A.USE_YN = #{useYn}

mapper.select:
/* PlatformCustomerMapper.selectCmpnyExists */
SELECT COUNT(1)
FROM TB_CMPNY A
WHERE A.CMPNY_CD = #{cmpnyCd}

mapper.insert:
/* PlatformCustomerMapper.upsertTokenQuota */
INSERT INTO TB_AI_TOKEN_QUOTA (
    CMPNY_CD
  , MONTHLY_TOKEN_LIMIT
  , INSERT_NO
) VALUES (
    #{cmpnyCd}
  , #{monthlyTokenLimit}
  , #{operatorUserCd}
) AS NEW
ON DUPLICATE KEY UPDATE
    MONTHLY_TOKEN_LIMIT = NEW.MONTHLY_TOKEN_LIMIT
  , UPDATE_NO   = #{operatorUserCd}
  , UPDATE_DATE = NOW()
